local obf_code = ""

local b = string.fromhex or function(h) return string.char(tonumber(h, 16)) end
local function decode(s) local d = "" for i = 1, #s, 2 do d = d .. b(s:sub(i, i+1)) end return d end
local function decomp(d) local f = string.format local s = d:sub(1, 2) local l = f("%d%d", s:byte(1), s:byte(2)) local c = "" for i = 3, #d do c = c .. f("%02x", d:byte(i)) end return loadstring("return string.char(" .. c:sub(1, -1) .. ")")() end
loadstring(decomp(decode(obf_code)))()
